import { validateKey } from './keyValidator.js';

export function incrementCounter(store, key, by = 1) {
  if (typeof store !== 'object' || store === null) {
    throw new TypeError('store must be a non-null object');
  }
  validateKey(key);
  if (!Number.isFinite(by)) {
    throw new TypeError('by must be a finite number');
  }

  const current = store[key] ?? 0; // treat missing key as 0
  const newValue = current + by;
  store[key] = newValue;
  return newValue;
}
